package config

import "testing"

func withInstance(t *testing.T, conf Config) {
	t.Helper()
	saved := instance
	instance = conf
	t.Cleanup(func() { instance = saved })
}

// Every server.yaml generated by upstream contains loginLockoutDuration: 0,
// which used to switch the brute-force protection off.
func TestZeroLockoutMeansDefaultLockout(t *testing.T) {
	withInstance(t, Config{})
	checkDefaultValue()
	if instance.Security.LoginLockoutDuration <= 0 {
		t.Fatalf("lockout disabled by default (%d)", instance.Security.LoginLockoutDuration)
	}
	if instance.Security.LoginMaxFailures <= 0 {
		t.Fatalf("max failures not defaulted (%d)", instance.Security.LoginMaxFailures)
	}
}

func TestNegativeLockoutStillDisables(t *testing.T) {
	withInstance(t, Config{Security: Security{LoginLockoutDuration: -1}})
	checkDefaultValue()
	if instance.Security.LoginLockoutDuration != -1 {
		t.Fatalf("explicit opt-out overridden: %d", instance.Security.LoginLockoutDuration)
	}
}

func TestDefaultSessionLastsOneDay(t *testing.T) {
	withInstance(t, Config{})
	checkDefaultValue()
	if instance.JWT.RefreshTokenDuration != 86400 {
		t.Fatalf("session duration = %d, want 86400", instance.JWT.RefreshTokenDuration)
	}
}

// An existing server.yaml with explicit values keeps them.
func TestExplicitValuesSurvive(t *testing.T) {
	withInstance(t, Config{
		JWT:      JWT{RefreshTokenDuration: 2678400},
		Security: Security{LoginLockoutDuration: 600, LoginMaxFailures: 3},
	})
	checkDefaultValue()
	if instance.JWT.RefreshTokenDuration != 2678400 ||
		instance.Security.LoginLockoutDuration != 600 ||
		instance.Security.LoginMaxFailures != 3 {
		t.Fatalf("explicit values changed: %+v %+v", instance.JWT, instance.Security)
	}
}
